{
  "title": "Proceso de Reserva y Recolección de Ejemplares en la Biblioteca Municipal de Villaficticia para Socias con Carné Vigente",
  "role": "Sociante Bibliotecario",
  "action": "reserva, recoja, anule una reserva",
  "benefit": "disfrutar de los títulos de la biblioteca sin contratiempos",
  "description": "Una sociante de la biblioteca de Villaficticia con permiso de acceso se vincula con los sistemas de la biblioteca de la municipalidad para reserva y recolección de ejemplares, siguiendo los protocolos establecidos, para acceder convenientemente a los títulos de sus interés.",
  "business_goal": "Optimizar el uso de la biblioteca y satisfacer la demanda de los usuarios de forma eficiente.",
  "scope_includes": [
    "Sistema de reservas",
    "Sistema de colección",
    "Proceso de notificación",
    "Reglas de préstamo para las personas con carné",
    "Condiciones especiales para la colección infantil y juvenil"
  ],
  "scope_excludes": [
    "Reservas de obras de referencia",
    "Reservas en préstamo",
    "Reservas no socias"
  ],
  "acceptance_criteria": [
    {
      "id": "CA-01",
      "title": "Reserva Caducada",
      "given": [
        "La reserva no se ha recolectado en 48 horas",
        "La persona socia no ha recogido el ejemplar"
      ],
      "when": [
        "La persona socio encabeza la cola"
      ],
      "then": [
        "La reserva se considera caducada",
        "El ejemplar pasa a la siguiente persona en la cola",
        "La reserva se registra como no recogida"
      ]
    },
    {
      "id": "CA-02",
      "title": "Reserva Cancelada",
      "given": [
        "La persona socia decide cancelar la reserva",
        "La reserva aún no ha sido convertida en préstamo"
      ],
      "when": [
        "Antes de la recolección del ejemplar"
      ],
      "then": [
        "La reserva se cancela sin penalizaciones",
        "El ejemplar se vuelve al inventario",
        "No hay sanción para la persona"
      ]
    },
    {
      "id": "CA-03",
      "title": "Renovación Prestado con Reserva Pendiente",
      "given": [
        "Existe un ejemplar en préstamo con reserva pendiente",
        "Se solicita una renovación"
      ],
      "when": [
        "La solicitud de renovación se realiza"
      ],
      "then": [
        "La renovación no se concede",
        "La reserva pendiente se cancela automáticamente"
      ]
    }
  ],
  "business_rules": [
    {
      "id": "RN-01",
      "description": "Para hacer reservas solo pueden ser las personas socias con carné válido sin sanciones activas que impidan reservarse."
    },
    {
      "id": "RN-02",
      "description": "Cada persona socia puede tener un máximo de 3 reservas activas."
    },
    {
      "id": "RN-04",
      "description": "La limitación máxima de ejemplares a tiempo en préstamo es de 8 ejemplares por persona socia."
    },
    {
      "id": "RN-02a",
      "description": "Las personas con carné infantil solo pueden reservar títulos de la colección infantil y juvenil, con un máximo de 3 reservas activas."
    },
    {
      "id": "RN-06",
      "description": "Si el ejemplar no se recoge dentro de 48 horas, la reserva caduca."
    },
    {
      "id": "RN-07",
      "description": "La persona socia puede cancelar la reserva en cualquier momento antes de la recolección sin penalidad."
    },
    {
      "id": "RN-09",
      "description": "Las personas con carné infantil no pueden reservar obras de referencia."
    }
  ],
  "assumptions": [
    "La persona socia tiene acceso al carné social válido.",
    "La persona socia conoce el sistema de reservas de la biblioteca.",
    "Todas las obras tengan un ejemplar disponible en la sede de recogida."
  ],
  "constraints": [
    "El límite máximo de ejemplares en tiempo en préstamo es de 8.",
    "El límite máximo de reservas activas es de 3 para las personas estándar y de 1 para las personas con carné infantil (si aplica).",
    "Las personas con carné infantil están restringidas a la colección infantil y juvenil."
  ],
  "dependencies": [],
  "alternate_flows": [],
  "exceptions": [],
  "related_features": [
    "Notificación de reserva caducada.",
    "Sistema de colas y orden de llegada.",
    "Capacitación en el uso del sistema de reserva."
  ],
  "priority": "Must",
  "open_questions": [
    "¿Qué sucede si hay más personas socias con carné activo de las que la versión 2 de la comisión de servicios proponen?",
    "¿Cómo se manejan los conflictos de reservas para títulos populares cuando el número de reservas supera el límite máximo de ejemplares?"
  ]
}

